use std::alloc::{GlobalAlloc, Layout, System};
use std::sync::atomic::{AtomicUsize, Ordering};

use renderer::graph::{BufferDesc, Graph};

struct Count;
static LIVE: AtomicUsize = AtomicUsize::new(0);
#[global_allocator]
static ALLOCATOR: Count = Count;

unsafe impl GlobalAlloc for Count {
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
        let pointer = unsafe { System.alloc(layout) };
        if !pointer.is_null() {
            LIVE.fetch_add(layout.size(), Ordering::Relaxed);
        }
        pointer
    }
    unsafe fn dealloc(&self, pointer: *mut u8, layout: Layout) {
        unsafe { System.dealloc(pointer, layout) };
        LIVE.fetch_sub(layout.size(), Ordering::Relaxed);
    }
    unsafe fn realloc(&self, pointer: *mut u8, layout: Layout, size: usize) -> *mut u8 {
        let replacement = unsafe { System.realloc(pointer, layout, size) };
        if !replacement.is_null() {
            if size >= layout.size() {
                LIVE.fetch_add(size - layout.size(), Ordering::Relaxed);
            } else {
                LIVE.fetch_sub(layout.size() - size, Ordering::Relaxed);
            }
        }
        replacement
    }
}

fn main() {
    const RESOURCES: usize = 1024;
    // Only allocator-requested heap bytes retained by the completed plan. This
    // is not allocator overhead, a process-memory sample, a GPU or timing claim.
    for live in [false, true] {
        let before = LIVE.load(Ordering::Relaxed);
        let mut graph = Graph::new();
        for _ in 0..RESOURCES {
            let buffer = graph.buffer("buffer", BufferDesc { size: 4 }).unwrap();
            graph.upload_buffer("upload", buffer, 0, vec![0; 4]).unwrap();
            if live {
                graph.readback_buffer("readback", buffer, 0, 4).unwrap();
            }
        }
        let plan = graph.compile().unwrap();
        drop(graph);
        let retained = LIVE.load(Ordering::Relaxed) - before;
        let passes = plan.pass_count();
        drop(plan);
        assert_eq!(LIVE.load(Ordering::Relaxed), before);
        println!("live={live} resources={RESOURCES} live_passes={passes} retained_requested_heap_bytes={retained}");
    }
}
